using RoR2;
using RoR2.Skills;
using System;
using System.Collections.Generic;
using System.Linq;
using TweyenR2RMod.Modules;
using TweyenR2RMod.Modules.Characters;
using TweyenR2RMod.Survivors.Tweyen.Components;
using TweyenR2RMod.Survivors.Tweyen.Projectiles;
using TweyenR2RMod.Survivors.Tweyen.SkillDefs;
using TweyenR2RMod.Survivors.Tweyen.SkillStates;
using UnityEngine;

namespace TweyenR2RMod.Survivors.Tweyen
{
    /// <summary>
    /// Tweyen, minimum viable version: model, colour skins, movement animations and placeholder skills.
    /// The model, display and materials are generated by TweyenUnityProject (Tweyen > Build All).
    /// RoR2 components (ChildLocator, HurtBoxes, CharacterModel...) are added here at load time.
    /// </summary>
    public class TweyenSurvivor : SurvivorBase<TweyenSurvivor>
    {
        public override string assetBundleName => "tweyenbundle";
        public override string bodyName => "TweyenBody";
        public override string masterName => "TweyenMonsterMaster";
        public override string modelPrefabName => "mdlTweyen";
        public override string displayPrefabName => "TweyenDisplay";

        public const string TWEYEN_PREFIX = TweyenPlugin.DEVELOPER_PREFIX + "_TWEYEN_";
        public override string survivorTokenPrefix => TWEYEN_PREFIX;

        /// <summary>Colour variants extracted from the game (vars 0-10).</summary>
        public const int SKIN_COUNT = 11;

        public override BodyInfo bodyInfo => new BodyInfo
        {
            bodyName = bodyName,
            bodyNameToken = TWEYEN_PREFIX + "NAME",
            subtitleNameToken = TWEYEN_PREFIX + "SUBTITLE",

            // Art/Icons/Character/TweyenCharacter.png: survivor select, logbook, scoreboard, ally cards
            characterPortrait = assetBundle.LoadAsset<Texture>("TweyenCharacter"),
            bodyColor = new Color(0.62f, 0.52f, 0.86f),
            sortPosition = 100,

            crosshair = Asset.LoadCrosshair("Standard"),
            podPrefab = LegacyResourcesAPI.Load<GameObject>("Prefabs/NetworkedObjects/SurvivorPod"),

            maxHealth = 110f,
            healthRegen = 1.5f,
            armor = 0f,

            moveSpeed = 7f * 1.15f, // 15% above the survivor default of 7

            jumpCount = 1,
        };

        public override CustomRendererInfo[] customRendererInfos =>
            skinTable.renderers.Select(r => new CustomRendererInfo { childName = r.renderer }).ToArray();

        public override UnlockableDef characterUnlockableDef => null;

        public override AssetBundle assetBundle { get; protected set; }
        public override GameObject bodyPrefab { get; protected set; }
        public override CharacterBody prefabCharacterBody { get; protected set; }
        public override GameObject characterModelObject { get; protected set; }
        public override CharacterModel prefabCharacterModel { get; protected set; }
        public override GameObject displayPrefab { get; protected set; }

        /// <summary>Which material every renderer uses in each skin (written by the Unity builder).</summary>
        [Serializable] public class SkinTable { public SkinRenderer[] renderers; }
        /// <summary>weapon: the bow (model id) a bow renderer belongs to, see <see cref="TweyenWeapons"/>.</summary>
        [Serializable] public class SkinRenderer { public string renderer; public string group; public string weapon; public string[] materials; }
        private SkinTable skinTable;

        private SkinDef[] skins;

        public override void Initialize()
        {
            base.Initialize();
        }

        public override void InitializeCharacter()
        {
            skinTable = JsonUtility.FromJson<SkinTable>(assetBundle.LoadAsset<TextAsset>("TweyenSkins").text);

            TweyenStates.Init();
            TweyenConfig.Init(assetBundle); // first: the tokens follow the Japanese name option
            TweyenTokens.Init();
            TweyenUnlocks.Init(assetBundle);

            base.InitializeCharacter();

            TweyenAnimEvents.Init(assetBundle);
            TweyenBuffs.Init(assetBundle);
            TweyenArrows.Init(assetBundle);
            TweyenClincherContent.Init();
            bodyPrefab.AddComponent<TweyenFallDamageShield>();
            // death: she falls as a ragdoll (bow in hand)
            TweyenRagdoll.Setup(characterModelObject);
            CharacterDeathBehavior deathBehavior = bodyPrefab.GetComponent<CharacterDeathBehavior>();
            if (deathBehavior) deathBehavior.deathState = new EntityStates.SerializableEntityStateType(typeof(TweyenDeathState));

            InitializeEntityStateMachines();
            InitializeSkills();
            // bow choice (loadout "Weapon Cosmetic" row): only the default bow shows until a choice is read
            TweyenWeapons.Init(bodyPrefab, assetBundle, skinTable.renderers);
            TweyenWeapons.Show(characterModelObject.GetComponent<ChildLocator>(), 0);
            if (displayPrefab) TweyenWeapons.SetupDisplay(displayPrefab);
            TweyenSounds.Init(bodyPrefab, characterModelObject, displayPrefab);
            InitializeSkins();
            InitializeCharacterMaster();
        }

        protected override void InitializeCharacterBodyPrefab()
        {
            characterModelObject = Prefabs.LoadCharacterModel(assetBundle, modelPrefabName);
            SetupChildLocator(characterModelObject, includeHurtboxes: true);

            bodyPrefab = Prefabs.CreateBodyPrefab(characterModelObject, bodyInfo);
            prefabCharacterBody = bodyPrefab.GetComponent<CharacterBody>();

            prefabCharacterModel = Prefabs.SetupCharacterModel(bodyPrefab, customRendererInfos);
            foreach (CharacterModel.RendererInfo info in prefabCharacterModel.baseRendererInfos)
            {
                PrepareMaterial(info.defaultMaterial);
            }
        }

        /// <summary>
        /// Converts to RoR2's shader and turns off backface culling: capes, hair and skirts are single-layer
        /// geometry meant to be seen from both sides.
        /// </summary>
        private static Material PrepareMaterial(Material mat)
        {
            if (!mat) return mat;
            return mat.ConvertDefaultShaderToHopoo().SetCull(false);
        }

        /// <summary>Names every renderer (and the hurtbox colliders) so the template's setup code can find them.</summary>
        private void SetupChildLocator(GameObject model, bool includeHurtboxes)
        {
            ChildLocator childLocator = model.GetComponent<ChildLocator>() ?? model.AddComponent<ChildLocator>();
            List<ChildLocator.NameTransformPair> pairs = new List<ChildLocator.NameTransformPair>();
            foreach (SkinRenderer r in skinTable.renderers)
            {
                pairs.Add(new ChildLocator.NameTransformPair { name = r.renderer, transform = model.transform.Find(r.renderer) });
            }
            if (includeHurtboxes)
            {
                pairs.Add(new ChildLocator.NameTransformPair { name = "MainHurtbox", transform = model.transform.Find("MainHurtbox") });
                Transform head = model.GetComponentsInChildren<Transform>(true).FirstOrDefault(t => t.name == "HeadHurtbox");
                if (head) pairs.Add(new ChildLocator.NameTransformPair { name = "HeadHurtbox", transform = head });
            }
            pairs.Add(new ChildLocator.NameTransformPair { name = "BowArmature", transform = model.transform.Find("BowArmature") });
            // tip of the drawn arrow (animated with the game's own arrow motion, not rendered): projectiles leave from here
            Transform arrowTip = model.GetComponentsInChildren<Transform>(true).FirstOrDefault(t => t.name == "ArrowTip");
            if (arrowTip) pairs.Add(new ChildLocator.NameTransformPair { name = "ArrowTip", transform = arrowTip });
            childLocator.transformPairs = pairs.ToArray();
        }

        /// <summary>
        /// The display has the same hierarchy as the body model, so it gets its own CharacterModel built from its
        /// own renderers (not the body prefab's), and its own ModelSkinController for skin previews.
        /// </summary>
        protected override void InitializeDisplayPrefab()
        {
            displayPrefab = assetBundle.LoadAsset<GameObject>(displayPrefabName);
            if (!displayPrefab)
            {
                Log.Error($"could not load display prefab {displayPrefabName}");
                return;
            }
            SetupChildLocator(displayPrefab, includeHurtboxes: false);

            CharacterModel characterModel = displayPrefab.GetComponent<CharacterModel>() ?? displayPrefab.AddComponent<CharacterModel>();
            characterModel.baseRendererInfos = skinTable.renderers
                .Select(r => displayPrefab.transform.Find(r.renderer).GetComponent<Renderer>())
                .Select(rend => new CharacterModel.RendererInfo
                {
                    renderer = rend,
                    defaultMaterial = PrepareMaterial(rend.sharedMaterial),
                    defaultShadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On,
                })
                .ToArray();
        }

        public override void InitializeEntityStateMachines()
        {
            Prefabs.ClearEntityStateMachines(bodyPrefab);
            Prefabs.AddMainEntityStateMachine(bodyPrefab, "Body", typeof(EntityStates.GenericCharacterMain), typeof(EntityStates.SpawnTeleporterState));
            Prefabs.AddEntityStateMachine(bodyPrefab, "Weapon");
            Prefabs.AddEntityStateMachine(bodyPrefab, "Weapon2");
        }

        #region skills
        public override void InitializeSkills()
        {
            Skills.ClearGenericSkills(bodyPrefab);
            // passive first, so its row is the first in the loadout
            TweyenPassive.InitSkill(bodyPrefab, assetBundle);

            // Stellar Arrow: her only primary. Firing it stops a sprint (no running-shot animation needed).
            SkillDef stellarArrow = Skills.CreateSkillDef<TweyenPrimarySkillDef>(new SkillDefInfo
            {
                skillName = "TweyenStellarArrow",
                skillNameToken = TWEYEN_PREFIX + "PRIMARY_STELLAR_ARROW_NAME",
                skillDescriptionToken = TWEYEN_PREFIX + "PRIMARY_STELLAR_ARROW_DESCRIPTION",
                skillIcon = assetBundle.LoadAsset<Sprite>("LethalRainSkill"),

                activationState = new EntityStates.SerializableEntityStateType(typeof(StellarArrow)),
                activationStateMachineName = "Weapon",
                interruptPriority = EntityStates.InterruptPriority.Any,

                baseRechargeInterval = 0f,
                baseMaxStock = 1,
                isCombatSkill = true,
                mustKeyPress = false,
                cancelSprintingOnActivation = true,
                canceledFromSprinting = false,
            });

            Skills.CreateGenericSkillWithSkillFamily(bodyPrefab, SkillSlot.Primary);
            Skills.AddPrimarySkills(bodyPrefab, stellarArrow);
            // Clincher: draw, then a huge piercing arrow (hitscan, like the Railgunner's Supercharged Railgun)
            SkillDef clincher = Skills.CreateSkillDef(new SkillDefInfo
            {
                skillName = "TweyenClincher",
                skillNameToken = TWEYEN_PREFIX + "SECONDARY_CLINCHER_NAME",
                skillDescriptionToken = TWEYEN_PREFIX + "SECONDARY_CLINCHER_DESCRIPTION",
                skillIcon = assetBundle.LoadAsset<Sprite>("ClincherSkill"),

                activationState = new EntityStates.SerializableEntityStateType(typeof(Clincher)),
                activationStateMachineName = "Body",
                // Skill: enough to cut Wheel of Death short (which only lets Skill and above interrupt it)
                interruptPriority = EntityStates.InterruptPriority.Skill,

                baseRechargeInterval = 15f,
                baseMaxStock = 1,
                isCombatSkill = true,
                mustKeyPress = true,
                cancelSprintingOnActivation = true,
                canceledFromSprinting = false,
                forceSprintDuringState = false,
            });

            // Asteroid Jaeger: hold to aim and mark, fire Multilock Hail with the primary
            SkillDef asteroidJaeger = TweyenAsteroidJaeger.Init(assetBundle);
            bodyPrefab.AddComponent<AsteroidJaegerMarks>();

            Skills.CreateGenericSkillWithSkillFamily(bodyPrefab, SkillSlot.Secondary);
            Skills.AddSecondarySkills(bodyPrefab, clincher, asteroidJaeger);
            // AI-controlled Tweyens (e.g. Artifact of Vengeance) always use Clincher: the AI can't aim and fire Asteroid Jaeger
            TweyenAILoadout.clincherDef = clincher;
            bodyPrefab.AddComponent<TweyenAILoadout>();
            // Wheel of Death: spin twice while dashing forward, firing 20 arrows around her
            SkillDef wheelOfDeath = Skills.CreateSkillDef(new SkillDefInfo
            {
                skillName = "TweyenWheelOfDeath",
                skillNameToken = TWEYEN_PREFIX + "UTILITY_WHEEL_OF_DEATH_NAME",
                skillDescriptionToken = TWEYEN_PREFIX + "UTILITY_WHEEL_OF_DEATH_DESCRIPTION",
                skillIcon = assetBundle.LoadAsset<Sprite>("WheelOfDeathSkill"),

                activationState = new EntityStates.SerializableEntityStateType(typeof(WheelOfDeath)),
                activationStateMachineName = "Body",
                interruptPriority = EntityStates.InterruptPriority.PrioritySkill,

                baseRechargeInterval = 7f, // the Huntress's Blink cooldown (placeholder until set)
                baseMaxStock = 1,
                isCombatSkill = true,
                mustKeyPress = false,
                cancelSprintingOnActivation = false,
                forceSprintDuringState = false,
            });

            // Valiant Weave: a Tactical Slide-style dash forward, firing one straight arrow
            SkillDef valiantWeave = Skills.CreateSkillDef(new SkillDefInfo
            {
                skillName = "TweyenValiantWeave",
                skillNameToken = TWEYEN_PREFIX + "UTILITY_VALIANT_WEAVE_NAME",
                skillDescriptionToken = TWEYEN_PREFIX + "UTILITY_VALIANT_WEAVE_DESCRIPTION",
                skillIcon = assetBundle.LoadAsset<Sprite>("ValiantWeaveSkill"),

                activationState = new EntityStates.SerializableEntityStateType(typeof(ValiantWeave)),
                activationStateMachineName = "Body",
                interruptPriority = EntityStates.InterruptPriority.Skill,

                baseRechargeInterval = 4f,
                baseMaxStock = 1,
                isCombatSkill = true,
                mustKeyPress = false,
                // like the Tactical Slide: doesn't stop a sprint, and runs during and after it
                cancelSprintingOnActivation = false,
                forceSprintDuringState = true,
                canceledFromSprinting = false,
            });

            Skills.CreateGenericSkillWithSkillFamily(bodyPrefab, SkillSlot.Utility);
            Skills.AddUtilitySkills(bodyPrefab, valiantWeave, wheelOfDeath); // Valiant Weave is the default
            Skills.AddUnlockablesToFamily(bodyPrefab.GetComponent<SkillLocator>().utility.skillFamily, null, TweyenUnlocks.renunciator); // "Tweyen: Renunciator"
            // Two-Crown's Strife: leap back, draw in the air while arrows gather around the bow, fire them all at once
            SkillDef twoCrownStrife = Skills.CreateSkillDef<OncePerStageSkillDef>(new SkillDefInfo
            {
                skillName = "TweyenTwoCrownStrife",
                skillNameToken = TWEYEN_PREFIX + "SPECIAL_TWO_CROWN_STRIFE_NAME",
                skillDescriptionToken = TWEYEN_PREFIX + "SPECIAL_TWO_CROWN_STRIFE_DESCRIPTION",
                skillIcon = assetBundle.LoadAsset<Sprite>("TwoCrownStrifeSkill"),

                activationState = new EntityStates.SerializableEntityStateType(typeof(TwoCrownStrife)),
                activationStateMachineName = "Body",
                // Skill: enough to cut Wheel of Death (and Clincher after its shot) short
                interruptPriority = EntityStates.InterruptPriority.Skill,

                // once per stage; each stage starts with this cooldown (shortened by cooldown items)
                baseRechargeInterval = 100f,
                baseMaxStock = 1,
                fullRestockOnAssign = false,
                isCombatSkill = true,
                mustKeyPress = true,
                cancelSprintingOnActivation = true,
                canceledFromSprinting = false,
                forceSprintDuringState = false,
            });

            Skills.CreateGenericSkillWithSkillFamily(bodyPrefab, SkillSlot.Special);
            Skills.AddSpecialSkills(bodyPrefab, twoCrownStrife);
            // Ancient Scepter's upgrade (Stellar Termination)
            TweyenScepter.Init(twoCrownStrife, assetBundle, bodyName);
        }
        #endregion skills

        #region skins
        public override void InitializeSkins()
        {
            ModelSkinController skinController = prefabCharacterModel.gameObject.AddComponent<ModelSkinController>();
            CharacterModel.RendererInfo[] defaultRendererInfos = prefabCharacterModel.baseRendererInfos;

            skins = new SkinDef[SKIN_COUNT];
            for (int v = 0; v < SKIN_COUNT; v++)
            {
                string token = v == 0 ? TWEYEN_PREFIX + "DEFAULT_SKIN_NAME" : TWEYEN_PREFIX + "SKIN_" + v + "_NAME";
                SkinDef skin = Skins.CreateSkinDef(token,
                    assetBundle.LoadAsset<Sprite>($"texTweyenSkin{v:00}"),
                    defaultRendererInfos,
                    prefabCharacterModel.gameObject,
                    SkinUnlockable(v));

                // rendererInfos follow customRendererInfos order, which follows the skin table
                for (int i = 0; i < skinTable.renderers.Length; i++)
                {
                    skin.skinDefParams.rendererInfos[i].defaultMaterial = LoadSkinMaterial(skinTable.renderers[i].materials[v]);
                }
                skins[v] = skin;
            }

            skinController.skins = skins;

            if (displayPrefab)
            {
                ModelSkinController displaySkins = displayPrefab.GetComponent<ModelSkinController>() ?? displayPrefab.AddComponent<ModelSkinController>();
                displaySkins.skins = skins;
            }
        }

        /// <summary>The achievement that unlocks skin <paramref name="v"/> (null: always available).</summary>
        private static UnlockableDef SkinUnlockable(int v)
        {
            switch (v)
            {
                case 2: // Glimmer
                case 3: // Stellar
                    return TweyenUnlocks.mastery;
                case 4: // Night
                    return TweyenUnlocks.moonslayer;
                case 5: // Silver Relic
                    return TweyenUnlocks.whole;
                case 6: // Sunlight (free with the "Unlock DLC skins" option)
                    return TweyenConfig.UnlockDlcSkins ? null : TweyenUnlocks.icarus;
                case 7: // Bloody
                    return TweyenUnlocks.darkHuntress;
                case 8: // Duality
                    return TweyenUnlocks.betrayal;
                case 9: // Umbra (free with the "Unlock DLC skins" option)
                    return TweyenConfig.UnlockDlcSkins ? null : TweyenUnlocks.voided;
                case 10: // Gold
                    return TweyenUnlocks.transcendence;
                default:
                    return null;
            }
        }

        private Material LoadSkinMaterial(string name)
        {
            // loaded directly: the template's name cache matches by substring, and these names share prefixes
            Material mat = assetBundle.LoadAsset<Material>(name);
            if (!mat)
            {
                Log.ErrorAssetBundle(name, assetBundle.name);
                return null;
            }
            return PrepareMaterial(mat);
        }
        #endregion skins

        public override void InitializeCharacterMaster()
        {
            // AI for Artifact of Vengeance etc.: Commando's, since the skills do nothing yet
            Prefabs.CloneDopplegangerMaster(bodyPrefab, masterName, "Commando");
        }
    }
}
